import { z } from "zod";
const zJoystickProps = z.object({
    label: z.string().optional(),
    disabled: z.boolean().optional(),
});
export function Joystick(define) {
    return define("JoystickWidget")
        .props(zJoystickProps)
        .shared({
        val: z.object({ x: z.number(), y: z.number() }),
    })
        .defaults((props) => ({
        val: { x: 0, y: 0 },
    }))
        .render((props) => ({
        label: props.label,
        disabled: props.disabled,
    }));
}
